import { DueDiligenceStatusLiquidacao } from '../enums';
import type { TDueDiligenceListFaseFilter } from '@/types/due-list-filters';
import { TCessionarioDue, TDueDiligenceDetailedCardItem } from '../types/dueItem';
import type { IKanbanCardResponsavelConsolidado } from './liquidacaoKanban';

export type TCessionarioDialogItemSnapshot = Pick<
    TDueDiligenceDetailedCardItem,
    'id' | 'cessionarios_vinculados' | 'extrato' | 'extrato_detail' | 'sub_status'
>;

export interface ILiqKanbanCardResponsaveisSnapshot {
    credor: string;
    people: IKanbanCardResponsavelConsolidado[];
}

import type { TStatusIdwall } from '../utils/idwall-status';

export type DueDiligenceFilterType = TDueDiligenceListFaseFilter;

const DUE_LIST_FASE_FILTER_VALUES: readonly DueDiligenceFilterType[] = [
    'TODOS',
    'REVISAO_VALOR_LOA',
    'PRE_DUE',
    'DUE_DILIGENCE',
    'REVISAO_DUE',
    'CONCLUIDO',
    'PENDENCIAS_IMPEDITIVAS',
];

/** Bookmarks: `REVISAO_DUE_DILIGENCE` → `REVISAO_DUE`; `CONCLUIDA` → `CONCLUIDO`. */
export function normalizeDueListFilterFromUrl(raw: string | null): DueDiligenceFilterType {
    if (!raw) return 'TODOS';
    if (raw === 'REVISAO_DUE_DILIGENCE') return 'REVISAO_DUE';
    if (raw === 'CONCLUIDA') return 'CONCLUIDO';
    if (DUE_LIST_FASE_FILTER_VALUES.includes(raw as DueDiligenceFilterType)) {
        return raw as DueDiligenceFilterType;
    }
    return 'TODOS';
}

export type LiquidacaoFilterType =
    | 'TODOS'
    | 'LIQ_APROVADO_RESSALVA'
    | 'LIQ_EM_LIQUIDACAO'
    | 'LIQ_EM_CESSAO';

export type RepactuacaoFilterType =
    | 'TODOS'
    | 'REVISAO_VALOR_LOA'
    | 'PRE_DUE'
    | 'DUE_DILIGENCE'
    | 'REVISAO_DUE';

const REPACTUACAO_FILTER_VALUES: RepactuacaoFilterType[] = [
    'TODOS',
    'REVISAO_VALOR_LOA',
    'PRE_DUE',
    'DUE_DILIGENCE',
    'REVISAO_DUE',
];

/** Normaliza `repacFilter` na URL para um valor de tab válido. */
export function normalizeRepactuacaoListFilterFromUrl(raw: string | null): RepactuacaoFilterType {
    if (!raw) return 'TODOS';
    const upper = raw.toUpperCase();
    if (upper === 'TODOS' || upper === 'TODO') return 'TODOS';
    if (upper === 'PRE_DUE_ATIVO' || upper === 'PRE_DUE_CEDENTE') return 'PRE_DUE';
    if (upper === 'REVISAO_DUE_DILIGENCE') return 'REVISAO_DUE';
    if (REPACTUACAO_FILTER_VALUES.includes(upper as RepactuacaoFilterType)) {
        return upper as RepactuacaoFilterType;
    }
    return 'TODOS';
}

/** Normaliza `liqFilter` na URL (ex.: bookmark `todos` em minúsculas). */
export function normalizeLiquidacaoListFilterFromUrl(raw: string | null): LiquidacaoFilterType {
    if (raw == null || raw === '') return 'TODOS';
    const upper = raw.toUpperCase();
    if (upper === 'TODOS' || upper === 'TODO') return 'TODOS';
    const allowed = Object.values(DueDiligenceStatusLiquidacao) as string[];
    if (allowed.includes(upper)) return upper as DueDiligenceStatusLiquidacao;
    return 'TODOS';
}

export interface IDueDiligenceStore {
    selectedDue: TDueDiligenceDetailedCardItem | null;
    setSelectedDue: (item: TDueDiligenceDetailedCardItem | null) => void;
    isObservationSheetOpen: boolean;
    setIsObservationSheetOpen: (open: boolean) => void;
    selectedObsItemId: string | null;
    setSelectedObsItemId: (id: string | null) => void;
    selectedObsItemName: string | undefined;
    setSelectedObsItemName: (name: string | undefined) => void;
    openObservationSheet: (id: string, name?: string) => void;
    closeObservationSheet: () => void;

    /** Sheet de histórico de pendências resolvidas (Due atual). */
    isPendenciasHistoricoSheetOpen: boolean;
    pendenciasHistoricoDueId: string | null;
    openPendenciasHistoricoSheet: (dueId: string) => void;
    closePendenciasHistoricoSheet: () => void;

    isLiqKanbanCardResponsaveisModalOpen: boolean;
    liqKanbanCardResponsaveisSnapshot: ILiqKanbanCardResponsaveisSnapshot | null;
    showLiqKanbanCardReponsaveisModal: (snapshot: ILiqKanbanCardResponsaveisSnapshot) => void;
    closeLiqKanbanCardResponsaveisModal: () => void;

    /** Snapshot ao abrir evita depender da página/filtro ativo da lista (mesmo padrão de observações). */
    isCessionarioDialogOpen: boolean;
    cessionarioDialogItemId: string | null;
    cessionarioDialogEditIndex: number | null;
    cessionarioDialogItemSnapshot: TCessionarioDialogItemSnapshot | null;
    openCessionarioDialog: (
        itemId: string,
        editIndex?: number | null,
        itemSnapshot?: TCessionarioDialogItemSnapshot | null,
        shouldAdvanceToAnaliseInvestidor?: boolean,
    ) => void;
    closeCessionarioDialog: () => void;
    cessionarioDialogShouldAdvanceToAnaliseInvestidor: boolean;
    /** Due com PATCH de `analise_investidor` em voo; segura a timeline na etapa de destino. */
    advancingToAnaliseInvestidorDueId: string | null;

    cessionarioListaOverrides: Record<string, TCessionarioDue[]>;
    setCessionarioListaOverride: (itemId: string, list: TCessionarioDue[]) => void;

    idwallDialogItem: TDueDiligenceDetailedCardItem | null;
    openIdwallDialog: (item: TDueDiligenceDetailedCardItem) => void;
    closeIdwallDialog: () => void;

    idwallStatusOverrides: Record<string, TStatusIdwall>;
    setIdwallStatusOverride: (id: string, status: TStatusIdwall) => void;
    removeIdwallStatusOverride: (id: string) => void;

    escrituraDialogItem: TDueDiligenceDetailedCardItem | null;
    openEscrituraDialog: (item: TDueDiligenceDetailedCardItem) => void;
    closeEscrituraDialog: () => void;

    escrituraStatusOverrides: Record<string, string | null>;
    setEscrituraStatusOverride: (id: string, status: string | null) => void;
    removeEscrituraStatusOverride: (id: string) => void;
}

