'use client';

import { buildFacetFilterOptions } from '@/components/Juridico/juridico-list-filter-options';
import { DUE_LIST_MODELO_DEFAULT } from '@/constants/due-diligence-query';
import { QueryKeys } from '@/constants/query-keys';
import { debounce } from '@/functions/debounce';
import {
    buildDueFaseCountFilters,
    buildOperationalListFiltersFromInput,
    resolveDueListModeloScope,
    resolveEstadoEnteDevedorForEsfera,
    resolvePreDueCountFromDashboard,
} from '@/functions/juridico/dueListOperationalFilters';
import { isUserMasterOrDev } from '@/functions/rulesVerification';
import { getCoordenadores } from '@/services/coodenadores';
import {
    getDueEnteDevedorOpcoes,
    getDueEstadoEnteDevedorOpcoes,
    getDueInvestidorOpcoes,
} from '@/services/due-diligence';
import { getAccessibleHosts } from '@/services/host';
import { useBrokerStore } from '@/store/useBroker';
import { useUserInfoStore } from '@/store/userInfo';
import type { IOperationalListFilterInput } from '@/types/due-list-filters';
import { useQuery } from '@tanstack/react-query';
import { parseAsInteger, parseAsString, useQueryStates } from 'nuqs';
import { useCallback, useEffect, useMemo, useState } from 'react';
import { ActiveViewType, DueDiligenceStatus, DueDiligenceStatusLiquidacao } from '../enums';
import { useDueDiligenceActiveView } from '../hooks/use-due-diligence-active-view';
import type {
    IFaseFilterOption,
    IOperationalFilterFieldHandlers,
} from '../interfaces/operationalFilters';
import type { IDueActiveViewTabsService, TLiquidationCountsResponse } from '../interfaces/services';
import {
    DueDiligenceFilterType,
    LiquidacaoFilterType,
    normalizeDueListFilterFromUrl,
    normalizeLiquidacaoListFilterFromUrl,
} from '../interfaces/store';
import {
    isDueDiligenceCoordinatorFollowRole,
    resolveLockedCoordinatorUsername,
} from '../utils/dueCoordinatorAccess';
import { resolveDueListStatisticsBrokerScope } from '../utils/dueListStatistics';

const DUE_FASE_DEFINITIONS: {
    id: DueDiligenceFilterType;
    label: string;
    isImpeditiva?: boolean;
}[] = [
        { id: 'TODOS', label: 'Todos' },
        { id: DueDiligenceStatus.REVISAO_VALOR_LOA, label: 'Revisão Valor/LOA' },
        { id: DueDiligenceStatus.PRE_DUE, label: 'Pré-Due' },
        { id: DueDiligenceStatus.DUE_DILIGENCE, label: 'Due Diligence' },
        { id: DueDiligenceStatus.REVISAO_DUE, label: 'Revisão DD' },
        { id: 'CONCLUIDO', label: 'Concluídos' },
        { id: 'PENDENCIAS_IMPEDITIVAS', label: 'Pend. Impeditivas', isImpeditiva: true },
    ];

const LIQUIDACAO_FASE_DEFINITIONS: { id: LiquidacaoFilterType; label: string }[] = [
    { id: 'TODOS', label: 'Todos' },
    { id: DueDiligenceStatusLiquidacao.LIQ_APROVADO_RESSALVA, label: 'Aprovado c/ ressalva' },
    { id: DueDiligenceStatusLiquidacao.LIQ_EM_LIQUIDACAO, label: 'Em liquidação' },
    { id: DueDiligenceStatusLiquidacao.LIQ_EM_CESSAO, label: 'Em cessão' },
];

function mapLiquidationCountsToRecord(
    api: TLiquidationCountsResponse | undefined,
): Record<LiquidacaoFilterType, number> {
    return {
        TODOS: api?.todos ?? 0,
        [DueDiligenceStatusLiquidacao.LIQ_APROVADO_RESSALVA]: api?.aprovado_ressalva ?? 0,
        [DueDiligenceStatusLiquidacao.LIQ_EM_LIQUIDACAO]: api?.em_liquidacao ?? 0,
        [DueDiligenceStatusLiquidacao.LIQ_EM_CESSAO]: api?.em_cessao ?? 0,
    };
}

function formatFaseLabel(label: string, count: number): string {
    return `${label} (${count})`;
}

export function useViewModelDiligenceFilter(service: IDueActiveViewTabsService) {
    const { activeView } = useDueDiligenceActiveView();
    const userRole = useUserInfoStore((state) => state.data.role);
    const currentUsername = useUserInfoStore((state) => state.data.username || state.data.user);
    const userHost = useUserInfoStore((state) => state.data.host);
    const isCoordenadorOrMaster = useBrokerStore((store) => store.isCoordenadorOrMaster);
    const showHostFilter = isUserMasterOrDev(userRole) || isCoordenadorOrMaster;
    const lockCoordinatorFilter = isDueDiligenceCoordinatorFollowRole(userRole);
    const lockedCoordinatorUsername = resolveLockedCoordinatorUsername(userRole, {
        user: currentUsername,
        username: currentUsername,
    });

    const [queryStates, setQueryStates] = useQueryStates({
        filter: parseAsString.withDefault('TODOS' as DueDiligenceFilterType),
        liqFilter: parseAsString.withDefault('TODOS' as LiquidacaoFilterType),
        modelo: parseAsString.withDefault(DUE_LIST_MODELO_DEFAULT),
        loa: parseAsString,
        credor: parseAsString,
        broker: parseAsString,
        priority_level: parseAsString,
        responsavel_scope: parseAsString,
        investidor_scope: parseAsString,
        investidor: parseAsString,
        esfera: parseAsString,
        ente_devedor: parseAsString,
        estado_ente_devedor: parseAsString,
        coordenador: parseAsString,
        host: parseAsString,
        page: parseAsInteger.withDefault(1),
    });

    const dueFase = normalizeDueListFilterFromUrl(queryStates.filter);
    const liquidacaoFase = normalizeLiquidacaoListFilterFromUrl(queryStates.liqFilter);
    const isLiquidacaoView = activeView === ActiveViewType.LIQUIDACAO;

    // `effectiveHost` só alimenta a UI (combobox, coordenadores). Sem host explícito
    // o filtro não vai para a API: o backend escopa por host próprio + delegadores.
    const explicitHost = queryStates.host?.trim() || null;
    const effectiveHost = explicitHost || userHost || '';

    const operationalInput = useMemo<IOperationalListFilterInput>(
        () => ({
            modelo: resolveDueListModeloScope(queryStates.modelo),
            loa: queryStates.loa,
            credor: queryStates.credor,
            broker: queryStates.broker,
            priority_level: queryStates.priority_level,
            responsavel_scope: queryStates.responsavel_scope,
            investidor_scope: queryStates.investidor_scope,
            investidor: queryStates.investidor,
            esfera: queryStates.esfera,
            ente_devedor: queryStates.ente_devedor,
            estado_ente_devedor: queryStates.estado_ente_devedor,
            coordenador: lockedCoordinatorUsername ?? queryStates.coordenador,
            host: explicitHost,
        }),
        [
            queryStates.modelo,
            queryStates.loa,
            queryStates.credor,
            queryStates.broker,
            queryStates.priority_level,
            queryStates.responsavel_scope,
            queryStates.investidor_scope,
            queryStates.investidor,
            queryStates.esfera,
            queryStates.ente_devedor,
            queryStates.estado_ente_devedor,
            queryStates.coordenador,
            lockedCoordinatorUsername,
            explicitHost,
        ],
    );

    const listFiltersForInvestidor = useMemo(
        () => buildOperationalListFiltersFromInput(operationalInput, currentUsername),
        [operationalInput, currentUsername],
    );

    const resetPage = useCallback(() => {
        void setQueryStates({ page: 1 });
    }, [setQueryStates]);

    const [localLoa, setLocalLoa] = useState(queryStates.loa ?? '');
    const [localCredor, setLocalCredor] = useState(queryStates.credor ?? '');
    const [localBroker, setLocalBroker] = useState(queryStates.broker ?? '');

    // Contagens das fases seguem o modelo selecionado para o label não divergir da lista.
    const modeloScope = resolveDueListModeloScope(queryStates.modelo);
    const statisticsBrokerScope = resolveDueListStatisticsBrokerScope(userRole, currentUsername);

    const { data: dashboardCounts, isLoading: isDueCountsLoading } = useQuery({
        queryKey: [
            'due-diligence',
            'dashboard-counts',
            statisticsBrokerScope ?? 'all',
            modeloScope ?? 'all',
            lockedCoordinatorUsername ?? 'all',
        ],
        queryFn: () =>
            service.getDashboardCounts({
                broker: statisticsBrokerScope,
                modelo: modeloScope,
                coordenador: lockedCoordinatorUsername,
            }),
        enabled: !isLiquidacaoView,
    });

    const { data: liquidacaoCounts, isLoading: isLiquidacaoCountsLoading } = useQuery({
        queryKey: [
            'due-diligence',
            'liquidacao-counts',
            modeloScope ?? 'all',
            lockedCoordinatorUsername ?? 'all',
        ],
        queryFn: () =>
            service.getLiquidacaoCount({
                modelo: modeloScope,
                coordenador: lockedCoordinatorUsername,
            }),
        enabled: isLiquidacaoView,
        staleTime: 30_000,
    });

    const { data: coordinatorsData, isLoading: isCoordinatorsLoading } = useQuery({
        queryKey: [QueryKeys.coordinators.list, effectiveHost],
        queryFn: () => getCoordenadores(effectiveHost || undefined),
    });

    const { data: accessibleHostsData, isLoading: isHostsLoading } = useQuery({
        queryKey: [QueryKeys.host.accessible],
        queryFn: getAccessibleHosts,
        enabled: showHostFilter,
    });

    const { data: investidorOpcoes = [], isLoading: isInvestidorOptionsLoading } = useQuery({
        queryKey: [
            QueryKeys.dueDiligence.investidorOpcoes,
            listFiltersForInvestidor,
            currentUsername,
            'due-diligence',
        ],
        queryFn: () =>
            getDueInvestidorOpcoes(listFiltersForInvestidor, 'due-diligence', currentUsername),
    });

    const { data: enteDevedorOpcoes = [], isLoading: isEnteDevedorOptionsLoading } = useQuery({
        queryKey: [
            QueryKeys.dueDiligence.enteDevedorOpcoes,
            listFiltersForInvestidor,
            currentUsername,
            isLiquidacaoView ? 'liquidation' : 'due-diligence',
        ],
        queryFn: () =>
            getDueEnteDevedorOpcoes(
                listFiltersForInvestidor,
                isLiquidacaoView ? 'liquidation' : 'due-diligence',
                currentUsername,
            ),
    });

    const dueProcessForEstado = isLiquidacaoView ? 'liquidation' : 'due-diligence';
    const { data: estadoEnteDevedorOpcoes = [], isLoading: isEstadoEnteDevedorOptionsLoading } =
        useQuery({
            queryKey: [
                QueryKeys.dueDiligence.estadoEnteDevedorOpcoes,
                listFiltersForInvestidor,
                currentUsername,
                dueProcessForEstado,
            ],
            queryFn: () =>
                getDueEstadoEnteDevedorOpcoes(
                    listFiltersForInvestidor,
                    dueProcessForEstado,
                    currentUsername,
                ),
            enabled: queryStates.esfera === 'ESTADUAL',
        });

    const dueFaseCounts: Record<DueDiligenceFilterType, number> = useMemo(
        () => ({
            TODOS: dashboardCounts?.todos ?? 0,
            [DueDiligenceStatus.REVISAO_VALOR_LOA]: dashboardCounts?.revisao_valor_loa ?? 0,
            [DueDiligenceStatus.PRE_DUE]: resolvePreDueCountFromDashboard(dashboardCounts),
            [DueDiligenceStatus.DUE_DILIGENCE]: dashboardCounts?.due_diligence ?? 0,
            [DueDiligenceStatus.REVISAO_DUE]: dashboardCounts?.revisao_due_diligence ?? 0,
            CONCLUIDO: dashboardCounts?.concluida ?? 0,
            PENDENCIAS_IMPEDITIVAS: dashboardCounts?.pendencias_impeditivas ?? 0,
        }),
        [dashboardCounts],
    );

    const liquidacaoFaseCounts = useMemo(
        () => mapLiquidationCountsToRecord(liquidacaoCounts),
        [liquidacaoCounts],
    );

    const faseOptions: IFaseFilterOption[] = useMemo(() => {
        if (isLiquidacaoView) {
            return LIQUIDACAO_FASE_DEFINITIONS.map((definition) => ({
                value: definition.id,
                label: formatFaseLabel(definition.label, liquidacaoFaseCounts[definition.id] ?? 0),
                count: liquidacaoFaseCounts[definition.id] ?? 0,
            }));
        }

        return DUE_FASE_DEFINITIONS.map((definition) => ({
            value: definition.id,
            label: formatFaseLabel(definition.label, dueFaseCounts[definition.id] ?? 0),
            count: dueFaseCounts[definition.id] ?? 0,
            isImpeditiva: definition.isImpeditiva,
        }));
    }, [dueFaseCounts, isLiquidacaoView, liquidacaoFaseCounts]);

    const faseValue = isLiquidacaoView ? liquidacaoFase : dueFase;

    const handleFaseChange = useCallback(
        (value: string) => {
            if (isLiquidacaoView) {
                void setQueryStates({
                    liqFilter: (value || 'TODOS') as LiquidacaoFilterType,
                    page: 1,
                });
                return;
            }

            void setQueryStates({
                filter: (value || 'TODOS') as DueDiligenceFilterType,
                page: 1,
            });
        },
        [isLiquidacaoView, setQueryStates],
    );

    const debouncedSetLoa = useMemo(
        () =>
            debounce((value: string) => {
                void setQueryStates({ loa: value === '' ? null : value, page: 1 });
            }, 500),
        [setQueryStates],
    );

    const debouncedSetCredor = useMemo(
        () =>
            debounce((value: string) => {
                void setQueryStates({ credor: value.trim() === '' ? null : value.trim(), page: 1 });
            }, 500),
        [setQueryStates],
    );

    const debouncedSetBroker = useMemo(
        () =>
            debounce((value: string) => {
                void setQueryStates({ broker: value.trim() === '' ? null : value.trim(), page: 1 });
            }, 500),
        [setQueryStates],
    );

    useEffect(() => {
        setLocalLoa(queryStates.loa ?? '');
    }, [queryStates.loa]);

    useEffect(() => {
        setLocalCredor(queryStates.credor ?? '');
    }, [queryStates.credor]);

    useEffect(() => {
        setLocalBroker(queryStates.broker ?? '');
    }, [queryStates.broker]);

    const coordinatorOptions = useMemo(
        () =>
            (coordinatorsData?.results ?? []).map((coordinator) => ({
                value: coordinator.username,
                label: coordinator.username,
            })),
        [coordinatorsData?.results],
    );

    const hostOptions = useMemo(
        () =>
            (accessibleHostsData ?? []).map((host) => ({
                value: host.domain,
                label: host.domain,
            })),
        [accessibleHostsData],
    );

    const investidorOptions = useMemo(
        () => investidorOpcoes.map((name) => ({ value: name, label: name })),
        [investidorOpcoes],
    );

    const enteDevedorOptions = useMemo(
        () => buildFacetFilterOptions(enteDevedorOpcoes, queryStates.ente_devedor),
        [enteDevedorOpcoes, queryStates.ente_devedor],
    );

    const estadoEnteDevedorOptions = useMemo(
        () =>
            buildFacetFilterOptions(estadoEnteDevedorOpcoes, queryStates.estado_ente_devedor).map(
                (option) => ({ value: option.value, label: option.value }),
            ),
        [estadoEnteDevedorOpcoes, queryStates.estado_ente_devedor],
    );

    const fieldHandlers: IOperationalFilterFieldHandlers = {
        modelo: queryStates.modelo ?? '',
        onModeloChange: (value) => {
            void setQueryStates({ modelo: value || null, page: 1 });
        },
        loa: localLoa,
        onLoaChange: (value) => {
            setLocalLoa(value);
            debouncedSetLoa(value);
        },
        credor: localCredor,
        onCredorChange: (value) => {
            setLocalCredor(value);
            debouncedSetCredor(value);
        },
        broker: localBroker,
        onBrokerChange: (value) => {
            setLocalBroker(value);
            debouncedSetBroker(value);
        },
        priorityLevel: queryStates.priority_level ?? '',
        onPriorityLevelChange: (value) => {
            void setQueryStates({ priority_level: value || null, page: 1 });
        },
        responsavelScope: queryStates.responsavel_scope ?? '',
        onResponsavelScopeChange: (value) => {
            void setQueryStates({ responsavel_scope: value || null, page: 1 });
        },
        investidorScope: queryStates.investidor_scope ?? '',
        onInvestidorScopeChange: (value) => {
            void setQueryStates({ investidor_scope: value || null, page: 1 });
        },
        investidor: queryStates.investidor ?? '',
        onInvestidorChange: (value) => {
            void setQueryStates({ investidor: value || null, page: 1 });
        },
        esfera: queryStates.esfera ?? '',
        onEsferaChange: (value) => {
            const nextEsfera = value || null;
            void setQueryStates({
                esfera: nextEsfera,
                estado_ente_devedor: resolveEstadoEnteDevedorForEsfera(
                    nextEsfera,
                    queryStates.estado_ente_devedor,
                ),
                page: 1,
            });
        },
        ente_devedor: queryStates.ente_devedor ?? '',
        onEnteDevedorChange: (value) => {
            void setQueryStates({ ente_devedor: value || null, page: 1 });
        },
        enteDevedorOptions,
        isEnteDevedorOptionsLoading,
        estado_ente_devedor: queryStates.estado_ente_devedor ?? '',
        onEstadoEnteDevedorChange: (value) => {
            void setQueryStates({ estado_ente_devedor: value || null, page: 1 });
        },
        estadoEnteDevedorOptions,
        isEstadoEnteDevedorOptionsLoading,
        coordenador: lockedCoordinatorUsername ?? queryStates.coordenador ?? '',
        onCoordenadorChange: (value) => {
            if (lockCoordinatorFilter) return;
            void setQueryStates({ coordenador: value || null, page: 1 });
        },
        lockCoordinatorFilter,
        // Valor do combobox = só filtro explícito. Nunca espelhar userHost aqui:
        // senão a UI parece filtrada por celer e um onChange grava host na URL.
        host: explicitHost ?? '',
        onHostChange: (value) => {
            const nextHost = value.trim();
            void setQueryStates({ host: nextHost ? nextHost : null, page: 1 });
        },
        faseValue,
        onFaseChange: handleFaseChange,
        faseOptions,
        isFaseLoading: isLiquidacaoView ? isLiquidacaoCountsLoading : isDueCountsLoading,
        isInvestidorOptionsLoading,
        isCoordinatorsLoading,
        isHostsLoading,
        showHostFilter,
        investidorOptions,
        coordinatorOptions,
        hostOptions,
        effectiveHost,
    };

    return {
        activeView,
        isLiquidacaoView,
        operationalInput,
        dueFase,
        liquidacaoFase,
        fieldHandlers,
        resetPage,
        buildCountFilters: () => buildDueFaseCountFilters(operationalInput, currentUsername),
    };
}

