'use client';

import { DropdownExportMethods } from '@/components/Juridico/DropdownExportMethods';
import { toDueExportModeloScope } from '@/functions/juridico/dueListOperationalFilters';
import type { TDueListStatusScope } from '@/types/due-list-filters';
import { useCardsExportDriverTour } from '../../hooks/useCardsExportDriverTour';
import { useOperationalListFilterQueryState } from '../../hooks/useOperationalListFilterQueryState';

interface IOperationalListExportActionsProps {
    dueProcess: 'due-diligence' | 'liquidation';
    statusScope?: TDueListStatusScope;
}

export function OperationalListExportActions({
    dueProcess,
    statusScope = 'backend-allow-list',
}: IOperationalListExportActionsProps) {
    useCardsExportDriverTour();
    const { dueListApiFilters, liquidacaoListApiFilters, modeloScope } =
        useOperationalListFilterQueryState();
    const filters = dueProcess === 'liquidation' ? liquidacaoListApiFilters : dueListApiFilters;

    return (
        <DropdownExportMethods
            filters={filters}
            dueProcess={dueProcess}
            tone="operational"
            modeloScope={toDueExportModeloScope(modeloScope)}
            statusScope={statusScope}
        />
    );
}

