'use client';

import { useMemo } from 'react';
import { ArquivamentosScreenService } from '../../services/ArquivamentosScreenService';
import { CessionarioService } from '../../services/CessionarioService';
import { useViewModelArquivamentosScreen } from '../../ViewModels/useViewModelArquivamentosScreen';
import { OperationalFiltersCard } from '../shared/OperationalFiltersCard';
import { ArquivadosFilterView } from './ArquivadosFilterView';
import { ArquivamentosScreenView } from './ArquivamentosScreenView';

export function ArquivamentosScreen() {
    const service = useMemo(() => new ArquivamentosScreenService(), []);
    const cessionarioService = useMemo(() => new CessionarioService(), []);
    const vm = useViewModelArquivamentosScreen({ service, cessionarioService });

    return (
        <>
            <OperationalFiltersCard>
                <ArquivadosFilterView />
            </OperationalFiltersCard>

            <div className="col-span-full">
                <ArquivamentosScreenView {...vm} />
            </div>
        </>
    );
}
